INSERT INTO `chapters` (`id`, `chapter_number`, `source_chapter_number`, `title`, `description`, `icon`, `is_active`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, 2, 'On the Trail of the Earliest People', 'Explore the lives of the earliest hunter-gatherers, their tools, shelters, food, and journey toward settled life.', '🏹', 1, 'AVAILABLE', '2026-09-10 04:26:56', '2026-09-10 04:26:56'),
(2, 2, 3, 'From Gathering to Growing Food', 'Discover how humans learned to grow crops, domesticate animals, and establish early settlements.', '🌾', 1, 'AVAILABLE', '2026-09-10 04:26:56', '2026-09-10 04:26:56'),
(3, 3, 4, 'In the Earliest Cities', 'Explore the Harappan civilization, its cities, architecture, drainage systems, crafts, trade, and daily life.', '🏛️', 1, 'AVAILABLE', '2026-09-10 04:26:56', '2026-09-10 04:26:56'),
(4, 4, 5, 'What Books and Burials Tell Us', 'Investigate ancient texts, the Rigveda, megalithic burials, iron tools, and clues about ancient societies.', '📖', 1, 'AVAILABLE', '2026-09-10 04:26:56', '2026-09-10 04:26:56'),
(5, 5, 8, 'Ashoka, the Emperor Who Gave Up War', 'Journey through the Mauryan Empire, the Kalinga war, and Ashoka’s transformation toward Dhamma and peace.', '🦁', 1, 'AVAILABLE', '2026-09-10 04:26:56', '2026-09-10 04:26:56'),
(6, 6, 1, 'What, Where, How and When?', 'Become a history detective and learn how historians use manuscripts, inscriptions, archaeology, and other sources.', '🔍', 1, 'COMING_SOON', '2026-09-10 04:26:56', '2026-09-10 14:05:53'),
(7, 7, 6, 'New Questions and Ideas', 'Explore the emergence of Buddhism, Jainism, the Upanishads, and new ways of thinking about life and society.', '☸️', 1, 'COMING_SOON', '2026-09-10 04:26:56', '2026-09-10 14:05:53'),
(8, 8, 7, 'Vital Villages, Thriving Towns', 'Discover ancient villages, farming, iron technology, craft production, trade, guilds, and growing towns.', '🌾', 1, 'COMING_SOON', '2026-09-10 04:26:56', '2026-09-10 14:05:53'),
(9, 9, 9, 'New Empires and Kingdoms', 'Explore the Gupta period, Samudragupta, Harshavardhana, Pallavas, Chalukyas, and changing political powers.', '⚔️', 1, 'COMING_SOON', '2026-09-10 04:26:56', '2026-09-10 14:05:53'),
(10, 10, 10, 'Buildings, Paintings and Books', 'Explore ancient architecture, stupas, temples, paintings, literature, mathematics, and scientific achievements.', '🏛️', 1, 'COMING_SOON', '2026-09-10 04:26:56', '2026-09-10 14:05:53');

